import { atom, read, update } from 'claude-code'
import type { EngineInterface, Register } from 'claude-code'

import type { MrView, RepoView, SessionView } from '../types'
import { API_BASE, CHECK_GLYPH, diffStat, isOpen, midTruncate, parseRemote, pickMrs, prIcon, repoLabel, stateOf, summarize, thousands, toView, tokenFromProfile } from './codeup'
import type { ApiChangeRequest, ApiCompare, ApiDetail, Repo } from './codeup'
import { dirsOf, mrKey, mrList, rememberDirs, stripBadges } from './session'

const view = atom({ plugin: 'codeup-mr', key: 'view' } as const, null)
const dirs = atom({ plugin: 'codeup-mr', key: 'dirs' } as const, [])
const expanded = atom({ plugin: 'codeup-mr', key: 'expanded' } as const, null)
const dismissed = atom({ plugin: 'codeup-mr', key: 'dismissed' } as const, [])
const POLL_MS = 60_000
const PAGE_SIZE = 100
const MAX_REPOS = 5
const BRANCH_MAX = 28
const PROFILES = ['.zshrc', '.zshenv', '.zprofile', '.bashrc', '.profile']
const SESSION_MCP = 'ccd_session_mgmt'
const NO_TOKEN = '未找到云效 token（设置 ALIBABA_CLOUD_YUNXIAO_ACCESS_TOKEN）'

async function git($: EngineInterface, dir: string, ...args: string[]): Promise<string> {
  const { exitCode, stdout } = await $.process.run(['git', '-C', dir, ...args], { timeoutMs: 5_000 }).catch(() => ({ exitCode: 1, stdout: '' }))
  return exitCode === 0 ? stdout.trim() : ''
}

async function resolveToken($: EngineInterface, configured: unknown): Promise<string | undefined> {
  if (typeof configured === 'string' && configured) return configured
  const fromEnv = await $.env.get('ALIBABA_CLOUD_YUNXIAO_ACCESS_TOKEN')
  if (fromEnv) return fromEnv
  const home = await $.env.get('HOME')
  for (const name of PROFILES) {
    const text = await $.fs.read(`${home}/${name}`).catch(() => '')
    const token = tokenFromProfile(text)
    if (token) return token
  }
  return undefined
}

async function api<T>($: EngineInterface, token: string, path: string): Promise<T> {
  const res = await $.http.fetch(`${API_BASE}/${path}`, { headers: { 'x-yunxiao-token': token } })
  if (!res.ok) throw new Error(`Codeup ${res.status}: ${res.text.slice(0, 120)}`)
  return JSON.parse(res.text) as T
}

// ponytail: module-level caches; reset on reload, which is fine
const repoIds = new Map<string, number>()
const roots = new Map<string, string>()
/** +/- per `${repo}!${id}@${head sha}`: the diff is fetched again only when the branch moves. */
const stats = new Map<string, { additions: number; deletions: number }>()
let tokenCache: { value: string | undefined } | null = null
let isTitleClean = false

async function fetchMrs($: EngineInterface, token: string, repo: Repo, branch: string, head: string): Promise<MrView[]> {
  let repoId = repoIds.get(repo.path)
  if (repoId === undefined) {
    const r = await api<{ id: number }>($, token, `${repo.org}/repositories/${encodeURIComponent(repo.path)}`)
    repoId = r.id
    repoIds.set(repo.path, repoId)
  }
  const base = `${repo.org}/repositories/${repoId}`
  // ponytail: Codeup ignores sourceBranch filtering, so scan the newest 100 MRs; page further if old branches matter
  const list = await api<ApiChangeRequest[]>($, token, `${repo.org}/changeRequests?projectIds=${repoId}&state=all&perPage=${PAGE_SIZE}`)
  // ponytail: the stats key ignores the target branch moving; add its sha if merged-in target commits must show
  return Promise.all(pickMrs(list, branch).map(async cr => {
    if (!isOpen(cr)) return toView(cr, repo.path)
    const key = `${repo.path}!${cr.localId}@${head}`
    const [detail, stat] = await Promise.all([
      api<ApiDetail>($, token, `${base}/changeRequests/${cr.localId}`).catch(() => undefined),
      stats.get(key) ?? api<ApiCompare>($, token, `${base}/compares?from=${encodeURIComponent(cr.targetBranch)}&to=${encodeURIComponent(cr.sourceBranch)}`)
        .then(diffStat)
        .then(s => (stats.set(key, s), s))
        .catch(() => undefined),
    ])
    return toView(cr, repo.path, detail, stat)
  }))
}

/** Git roots of the session's cwd and of every directory it touched, cwd first, deduped. */
async function sessionRoots($: EngineInterface): Promise<string[]> {
  const touched = await read($, dirs)
  const candidates = [await $.session.cwd(), ...[...(Array.isArray(touched) ? touched : [])].reverse()]
  const found: string[] = []
  for (const dir of candidates) {
    if (!roots.has(dir)) roots.set(dir, await git($, dir, 'rev-parse', '--show-toplevel'))
    const root = roots.get(dir)
    if (root && !found.includes(root)) found.push(root)
    if (found.length >= MAX_REPOS) break
  }
  return found
}

async function repoView($: EngineInterface, token: string, root: string): Promise<RepoView | null> {
  const [remote, branch, upstream, local] = await Promise.all([
    git($, root, 'remote', 'get-url', 'origin'),
    git($, root, 'branch', '--show-current'),
    git($, root, 'rev-parse', '@{u}'),
    git($, root, 'rev-parse', 'HEAD'),
  ])
  const repo = parseRemote(remote)
  if (!repo || !branch) return null
  const name = repoLabel(repo.path)
  return fetchMrs($, token, repo, branch, upstream || local)
    .then(mrs => ({ root, repo: name, branch, mrs }))
    .catch((err: Error) => ({ root, repo: name, branch, mrs: [], error: err.message }))
}

/** Removes title badges older versions wrote (Desktop only); runs until one check finds none. */
async function cleanTitle($: EngineInterface) {
  if (isTitleClean) return
  try {
    const got = await $.mcp.call(SESSION_MCP, 'get_session', { session_id: 'self' })
    const text = got.content[0]?.text
    const current = typeof text === 'string' ? (JSON.parse(text) as { title?: string }).title : undefined
    if (got.isError || typeof current !== 'string') return
    const title = stripBadges(current)
    if (title !== current) await $.mcp.call(SESSION_MCP, 'set_session_title', { session_id: 'self', title })
    isTitleClean = true
  } catch {
    isTitleClean = true // not a Desktop session: no session-management server
  }
}

async function refresh($: EngineInterface, configuredToken: unknown) {
  const found = await sessionRoots($)
  if (!found.length) {
    await update($, view, () => null)
    return
  }
  tokenCache ??= { value: await resolveToken($, configuredToken) }
  const token = tokenCache.value
  if (!token) {
    await update($, view, (): SessionView => ({ repos: [], error: NO_TOKEN }))
    return
  }
  const repos = (await Promise.all(found.map(root => repoView($, token, root)))).filter((r): r is RepoView => r !== null)
  await update($, view, (): SessionView => ({ repos }))
}

export const register: Register = (on, options) => {
  on('session.start', async ($, e, next) => {
    const result = await next(e)
    await $.command.register({ name: 'mr', description: '列出本会话涉及仓库的 Codeup MR 及链接' })
    void refresh($, options.token)
    void cleanTitle($)
    $.clock.every(POLL_MS, () => void refresh($, options.token))
    return result
  })

  on('turn.complete', async ($, e, next) => {
    const result = await next(e)
    await refresh($, options.token)
    await cleanTitle($)
    return result
  })

  on('tool.call', async ($, e, next) => {
    const ran = await next(e)
    const home = (await $.env.get('HOME')) ?? ''
    const added = dirsOf(e.tool, e as { file_path?: unknown; notebook_path?: unknown; command?: unknown }, home)
    if (added.length) await update($, dirs, known => rememberDirs(Array.isArray(known) ? known : [], added))
    return ran
  })

  on('command.run', { command: 'mr' }, async $ => {
    await refresh($, options.token)
    const v = await read($, view)
    return { text: v?.error ?? mrList(v?.repos ?? [], state => stateOf(state).label) }
  })

  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    const v = await read($, view)
    if (e.props.hasSurvey || !v) return next(e)
    const hidden = await read($, dismissed)
    const isHidden = (mr: MrView) => Array.isArray(hidden) && hidden.includes(mrKey(mr))
    const mrs = v.repos.flatMap(r => r.mrs).filter(mr => !isHidden(mr))
    const errors = v.error ? [v.error] : v.repos.flatMap(r => (r.error ? [`${r.repo}: ${r.error}`] : []))
    if (!mrs.length && !errors.length) return next(e)

    const ui = $.ui.resolve(e)
    const { Box, Button, Link, Text } = ui
    const open = await read($, expanded)

    const icon = (mr: MrView) => {
      const s = stateOf(mr.state)
      return 'Svg' in ui
        ? <ui.Svg source={prIcon(s.hex)} alt={s.label} width={16} height={16} />
        : <Text color={s.tone}>⑂</Text>
    }

    const row = (mr: MrView) => {
      const key = mrKey(mr)
      const s = stateOf(mr.state)
      const sum = CHECK_GLYPH[summarize(mr.checks)]
      const isOpenRow = open === key
      const hasStats = mr.additions !== undefined && mr.deletions !== undefined
      return (
        <Box key={`mr-${key}`} flexDirection="column">
          <Box gap={2} alignItems="center">
            {icon(mr)}
            <Link href={mr.url} label={`!${mr.id}`} />
            <Text color={s.tone}>{s.label}</Text>
            <Text dimColor>{mr.repo}</Text>
            <Text dimColor>{midTruncate(mr.source, BRANCH_MAX)} → {mr.target}</Text>
            <Box flexGrow={1} />
            {hasStats ? (
              <Box borderStyle="round" paddingX={1} gap={1}>
                <Text color="diffAdded" bold>+{thousands(mr.additions ?? 0)}</Text>
                <Text color="diffRemoved" bold>-{thousands(mr.deletions ?? 0)}</Text>
              </Box>
            ) : null}
            {mr.checks.length ? (
              <Button key={`checks-${key}`} onPress={() => update($, expanded, cur => (cur === key ? null : key))}>
                <Text color={sum.tone}>{sum.glyph}</Text> 检查 {isOpenRow ? '⌃' : '⌄'}
              </Button>
            ) : null}
            <Link href={mr.url} label="打开 ↗" />
            <Button key={`dismiss-${key}`} role="dismiss" plain label="×" dimColor onPress={() => update($, dismissed, list => [...(Array.isArray(list) ? list : []), key])} />
          </Box>
          {isOpenRow ? (
            <Box flexDirection="column" paddingX={3}>
              {mr.checks.map(c => {
                const g = CHECK_GLYPH[c.status]
                return (
                  <Box key={`check-${key}-${c.label}`} gap={1}>
                    <Text color={g.tone}>{g.glyph}</Text>
                    <Text>{c.label}</Text>
                  </Box>
                )
              })}
            </Box>
          ) : null}
        </Box>
      )
    }

    return (
      <Box flexDirection="column">
        {mrs.map(row)}
        {errors.map(err => <Text key={`err-${err}`} dimColor>Codeup MR · {err}</Text>)}
      </Box>
    )
  })
}

